/*
 * A037348  Numbers whose base-3 and base-7 expansions have no digits in
 *          common.
 * https://oeis.org/A037348
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 68, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Numbers whose base‑3 and base‑7 expansions have no digits in common. */
/* The sequence is generated by searching integers, testing whether the
 * set of digits occurring in base‑3 representation is disjoint from the
 * set of digits occurring in base‑7 representation.  The function
 * a(idx_t n) returns the nth term (1‑based offset).  The result is
 * memoised so that repeated calls are efficient. */
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* Check whether an integer has no common digits in base‑3 and base‑7. */
static bool good(uint64_t n)
{
    uint64_t t = n;
    int mask3 = 0;
    /* base‑3 digits */
    do {
        mask3 |= 1 << (t % 3);
        t /= 3;
    } while (t > 0);

    t = n;
    int mask7 = 0;
    /* base‑7 digits */
    do {
        mask7 |= 1 << (t % 7);
        t /= 7;
    } while (t > 0);

    return (mask3 & mask7) == 0;
}

/* Cached values of the sequence. */
static seq_t *cache = NULL;
static idx_t cache_cap = 0;
static idx_t cache_len  = 0;
static uint64_t next_cand = 0;   /* candidate to test next */

/* Grow the cache to ensure at least 'need' elements can be stored. */
static void grow_cache(idx_t need)
{
    if (need <= cache_cap)
        return;
    idx_t new_cap = cache_cap == 0 ? 16 : cache_cap * 2;
    while (new_cap < need)
        new_cap *= 2;
    seq_t *new_cache = (seq_t *)malloc(new_cap * sizeof(seq_t));
    if (!new_cache) {
        /* In a robust program we would handle this error; here we
         * simply abort (sequence is unlikely to need > 2^32 terms). */
        exit(1);
    }
    if (cache) {
        for (idx_t i = 0; i < cache_len; ++i)
            new_cache[i] = cache[i];
        free(cache);
    }
    cache     = new_cache;
    cache_cap = new_cap;
}

/* Return the nth term of the sequence (n >= 1). */
seq_t a(idx_t n)
{
    if (n == 0)
        return (seq_t)0;   /* undefined but benign */

    /* Ensure we have computed up to the requested index. */
    while (cache_len < n) {
        ++next_cand;
        if (good(next_cand)) {
            grow_cache(cache_len + 1);
            cache[cache_len] = (seq_t)next_cand;
            ++cache_len;
        }
    }
    return cache[n - 1];
}
